#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_ROWS 100
#define MAX_ROW_LEN 10000

/* 链表节点 */
typedef struct Node {
    int val;
    struct Node *next;
} Node;

/* 链表 */
typedef struct Link {
    int size;
    Node *head;
    Node *tail;
} Link;

// 创建链表
Link *new_Link() {
    Link *link = (Link *) malloc(sizeof(Link));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

// 尾插
void addLast_Link(Link *link, int val) {
    Node *node = (Node *) malloc(sizeof(Node));
    node->val = val;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

// 头删
int removeFirst_Link(Link *link) {
    if (link->size == 0) exit(-1);

    Node *removed = link->head;
    if (link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    int val = removed->val;
    free(removed);

    return val;
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    getchar();

    Link *lists[MAX_ROWS];
    int lists_size = 0;

    char s[MAX_ROW_LEN];
    while (gets(s)) {
        // 本地测试，以空行作为输入截止条件
        if (strlen(s) == 0) break;

        Link *link = new_Link();

        char *token = strtok(s, " ");
        while (token != NULL) {
            addLast_Link(link, atoi(token));
            token = strtok(NULL, " ");
        }

        lists[lists_size++] = link;
    }

    // 窗口矩阵，k行n列，每一列对应一个窗口，这里将二维矩阵一维化，方便后面赋值
    int windows[k * n];
    // 窗口矩阵中正在赋值的索引位置
    int idx = 0;
    // 正在从第level个列表中取值
    int level = 0;

    // 当窗口矩阵填满后，结束循环
    while (idx < k * n) {
        // 当前轮次是否发生了"借"动作
        int flag = 0;

        // 从第level个列表中取前n个元素
        for (int i = 0; i < n; i++) {
            windows[idx++] = removeFirst_Link(lists[level]);

            // 如果第level个列表没有元素了，则继续切到下一个列表中"借"
            if (lists[level]->size == 0 && lists_size > 1) {
                // 删除第level个空列表
                for (int j = level + 1; j < lists_size; j++) {
                    lists[j - 1] = lists[j];
                }
                lists_size--;
                level %= lists_size; // 防止越界
                flag = 1;   // 发生了"借"动作
            }
        }

        // 如果没有发生"借"动作，则需要切到下一行
        if (!flag) {
            level = (level + 1) % lists_size; // 防止越界
        }
    }

    // 遍历列号
    for (int j = 0; j < n; j++) {
        // 遍历行号
        for (int i = 0; i < k; i++) {
            // 按列打印
            printf("%d", windows[i * n + j]);
            if (j != n - 1 || i != k - 1) {
                printf(" ");
            }
        }
    }

    return 0;
}
